class Solution {
  public int minGenerations(int[][] points, int[] target) {
    boolean[] have = new boolean[343];
    List<Integer> all = new ArrayList<>();
    for (int[] p : points) {
      int id = p[0] * 49 + p[1] * 7 + p[2];
      if (!have[id]) {
        have[id] = true;
        all.add(id);
      }
    }
    int goal = target[0] * 49 + target[1] * 7 + target[2];
    if (have[goal]) return 0;
    for (int gen = 1; ; gen++) {
      List<Integer> fresh = new ArrayList<>();
      for (int i = 0; i < all.size(); i++) {
        for (int j = i + 1; j < all.size(); j++) {
          int a = all.get(i), b = all.get(j);
          int x = (a / 49 + b / 49) / 2, y = (a / 7 % 7 + b / 7 % 7) / 2, z = (a % 7 + b % 7) / 2;
          int id = x * 49 + y * 7 + z;
          if (!have[id]) {
            have[id] = true;
            fresh.add(id);
          }
        }
      }
      if (fresh.isEmpty()) return -1;
      all.addAll(fresh);
      if (have[goal]) return gen;
    }
  }
}
